#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_compileFromAST_unsupported_ast_node_returns_null(void) {
    // Setup: create an ASTNode with unsupported content (not '\0', not a literal, not '
', '|', or '*')
    // Let's use content = '^' (assuming isLiteral('^') == false and not handled in switch)
    struct ASTNode* node = createNode('^');
    TEST_ASSERT_NOT_NULL(node);
    node->left = NULL;
    node->right = NULL;

    // Test: call compileFromAST with unsupported node
    struct NFA* nfa = compileFromAST(node);

    // Assert: should return NULL
    TEST_ASSERT_NULL(nfa);

    // Cleanup
    destroyNode(node);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_compileFromAST_unsupported_ast_node_returns_null);
    return UNITY_END();
}

